  font-size: 1.1rem;
  font-weight: 700;
  cursor: pointer;
  color: inherit;
  text-decoration: underline;
  text-decoration-color: transparent;
}

.note-title:hover,
.note-title:focus-visible {
  text-decoration-color: currentColor;
}

.note-body {
  grid-column: 2;
}

.note-body a {
  color: #6366f1;
}
